"""Sticks the css into a <style> tag."""
def add_css_to_html(html: str, css: str) -> str {
    return f'''<style>{css}</style>{html}''';
}

test_blocks:
test "t0" {
    assert (
        add_css_to_html(
            '''<h1>Hello World</h1>
<p>This is a paragraph!</p>''',
            'h1 { background-color: #00FF00; }'
        )
        == '<style>h1 { background-color: #00FF00; }</style><h1>Hello World</h1>\n<p>This is a paragraph!</p>'
    );;
}

test "t1" {
    assert (
        add_css_to_html(
            '<h1>Hello World</h1>',
            'h1 { background-color: #00FF00; } h1 { font-family: Comic Sans MS; }'
        )
        == '<style>h1 { background-color: #00FF00; } h1 { font-family: Comic Sans MS; }</style><h1>Hello World</h1>'
    );;
}

test "t2" {
    assert (
        add_css_to_html(
            'Hello World',
            'body { background-color: #00FF00; } body { font-family: Comic Sans MS; }'
        )
        == '<style>body { background-color: #00FF00; } body { font-family: Comic Sans MS; }</style>Hello World'
    );;
}

test "t3" {
    assert (
        add_css_to_html('<h1>Hello World</h1>', 'h1 { background-color: #00FF00; }')
        == '<style>h1 { background-color: #00FF00; }</style><h1>Hello World</h1>'
    );;
}

test "t4" {
    assert (
        add_css_to_html(
            '<h1>This is a Title</h1>',
            'font-size: 200%; font-family: Georgia, serif; background-color: black; color: white; padding: 10px;'
        )
        == '''<style>font-size: 200%; font-family: Georgia, serif; background-color: black; color: white; padding: 10px;</style><h1>This is a Title</h1>'''
    );;
}

test "t5" {
    assert (
        add_css_to_html(
            '<h1>My Heading</h1>', '.heading { font-size: 40px; color: blue; }'
        )
        == '''<style>.heading { font-size: 40px; color: blue; }</style><h1>My Heading</h1>'''
    );;
}

